src = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = g[r][c]
            if color and all(g[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
    # Extend each square's center row and column across the grid.
    for r, c, color in objects:
        for j in range(w):
            g[r][j] = color
        for i in range(h):
            g[i][c] = color
    # Crossings of lines from different objects remain empty.
    for r, c, color in objects:
        for rr, cc, other in objects:
            if color != other:
                g[r][cc] = 0
                g[rr][c] = 0
    return g
'''
